package io.knowledgebrain.collaboration;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.mock.web.MockHttpServletRequest;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class ReviewSignalExportIntegrationTest {
 @Test void exportIsContentFreeOrderedHashPinnedAndBounded(){var f=new SubmissionFeedbackStoreIntegrationTest();f.setup();f.change(0,1,"PRIVATE OPINION SENTINEL");f.change(1,1,"PRIVATE OPINION CHANGED");var controller=new ReviewSignalExportController(f.f.f.source,"a".repeat(43));var page=controller.page(null,1);assertEquals(1,page.items().size());assertNotNull(page.nextAfter());var next=controller.page(page.nextAfter(),100);assertFalse(next.items().isEmpty());String raw=tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(page);assertFalse(raw.contains("PRIVATE OPINION"));assertFalse(raw.contains("content"));var signal=page.items().getFirst();var bytes=f.f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,signal.eventId());assertEquals(ReviewSignal.hash(bytes),signal.payloadHash());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->controller.page(null,101));}
 @Test void dedicatedTlsServiceCredentialRequired(){var f=new SubmissionFeedbackStoreIntegrationTest();f.setup();var api=new ReviewSignalExportController(f.f.f.source,"a".repeat(43));var r=new MockHttpServletRequest("GET","/internal/collaboration/review-signals");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->api.export(r));r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));assertEquals("no-store",api.export(r).getHeaders().getCacheControl());r.addHeader("Cookie","private=secret");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->api.export(r));}
}
